#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;

int gcdVal, xVal, yVal;

void computeGCD(int a, int b) {
    if (b == 0) {
        gcdVal = a; xVal = 1; yVal = 0;
    } else {
        computeGCD(b, a % b);
        int tempX = xVal - a / b * yVal;
        xVal = yVal;
        yVal = tempX;
    }
}

int getInverse(int a) {
    computeGCD(a, MOD);
    return xVal < 0 ? xVal + MOD : xVal;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, k;
    cin >> n >> m >> k;
    int invM = getInverse(m);
    vector<long long> dp(k + 1, 0);
    dp[0] = 1;

    for (int i = 0; i < k; i++) {
        for (int d = k - 1; d >= 0; d--) {
            if (dp[d] != 0) {
                dp[d + 1] = (dp[d + 1] + dp[d] * (n - d)) % MOD;
                dp[d] = (dp[d] * d) % MOD;
            }
        }
    }

    long long p = 1, ans = 0;
    for (int d = 1; d <= k; d++) {
        p = p * invM % MOD;
        ans = (ans + dp[d] * p) % MOD;
    }
    cout << ans << "\n";
    return 0;
}
